    protected override async Task OnInitializedAsync()
    {
        try
        {
            isLoading = true;
            hasError = false;

            var existing = await invoiceService.GetByIdAsync(Id);
            Console.WriteLine($"Fetched Invoice Type: {existing?.data.name}");    
            if (existing is null)
            {
                hasError = true;
            }
            else
            {
                model = new InvoiceType
                {
                    id = existing.data.id,
                    name = existing.data.name
                };
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message);
            hasError = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleSubmit()
    {
        isSaving = true;
        model.name = model.name?.Trim() ?? "";

        if (string.IsNullOrWhiteSpace(model.name))
        {
            message = "Invoice type name is required.";
            isSuccess = false;
            isSaving = false;
            return;
        }

        try
        {
            var result = await invoiceService.UpdateAsync(model.id, model);

            isSuccess = result?.success ?? false;
            message = result?.message ?? "No response received";

            if (isSuccess)
            {
                await Task.Delay(1000);
                Nav.NavigateTo("/invoice/view-invoice-types");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message);
            isSuccess = false;
            message = "Failed to update Invoice Type.";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void Cancel()
    {
        Nav.NavigateTo("/invoice/view-invoice-types");
    }

